+package org.ratpackframework.handler;
+
+import org.jboss.netty.buffer.ChannelBuffer;
+import org.jboss.netty.handler.codec.http.HttpResponse;
+import org.jboss.netty.handler.codec.http.HttpResponseStatus;
+
+@SuppressWarnings("ThrowableResultOfMethodCallIgnored")
+public class FallbackErrorHandlingTemplateRenderer implements ResultHandler<ChannelBuffer> {
+
+  private final HttpExchange exchange;
+  private final String operationDescription;
+
+  public FallbackErrorHandlingTemplateRenderer(HttpExchange exchange, String operationDescription) {
+    this.exchange = exchange;
+    this.operationDescription = operationDescription;
+  }
+
+  @Override
+  public void handle(Result<ChannelBuffer> event) {
+    HttpResponse response = exchange.getResponse();
+    if (event.isFailure()) {
+      event.getFailure().printStackTrace(System.err);
+      response.setStatus(HttpResponseStatus.INTERNAL_SERVER_ERROR);
+      exchange.end("plain/text", "Unhandled exception occurred during " + operationDescription);
+    } else {
+      exchange.end(event.getValue());
+    }
+  }
+}

