+          parentInjector = injector;
+          return this;
+        }
+
+        @Override
+        public Spec baseDir(Supplier<? extends Path> supplier) {
+          baseDirSupplier = supplier;
+          return this;
+        }
+      };
+    }
+
+  }
+}

