+        execHarness.exec().start {
+          def stream = Streams.yield {
+            it.requestNum < elements ? elements : null
+          }
+
+          stream = execHarness.stream(stream)
+
+          stream = Streams.flatMap(stream) { n ->
+            execHarness.blocking { n * 2 }
+          }
+
+          stream.subscribe(s)
+        }
+      }
+    }
+  }
