+    DefaultMapSessionStore defaultMapSessionStore = new DefaultMapSessionStore(maxEntries, ttlMinutes);
+    sessionManager.addSessionListener(defaultMapSessionStore);
+    return defaultMapSessionStore;
+  }
+
+}

